-- State transitions declared for SupplierQuotation (shadow: an undeclared move raises a WARNING).
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION buying.supplier_quotations_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('submitted', 'ordered'))
       ) THEN
        RAISE WARNING 'state_transition_not_declared: supplier_quotations.status % -> %', OLD."status", NEW."status";
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS supplier_quotations_status_transition_check ON buying.supplier_quotations;
CREATE TRIGGER supplier_quotations_status_transition_check
    BEFORE UPDATE OF "status" ON buying.supplier_quotations
    FOR EACH ROW EXECUTE FUNCTION buying.supplier_quotations_status_transition_check();
